mapper.select:
SELECT A.*, B.* FROM ( SELECT tt1.rnum no, tt1.content_id, tt1.genre_id FROM ( SELECT ROWNUM rnum, t1.* FROM ( SELECT * FROM content_genre
ORDER BY content_id ASC, genre_id ASC ) t1 WHERE ROWNUM <= (#{pageSize} * (#{pageNo} - 1) + #{pageSize}) ) tt1 WHERE rnum >= (#{pageSize} * (#{pageNo} - 1) + 1) ) A CROSS JOIN ( SELECT COUNT(*) total_cnt FROM content_genre
) B

SELECT content_id,
       genre_id
  FROM content_genre
 WHERE content_id = #{contentId}
   AND genre_id = #{genreId}

mapper.insert:
INSERT INTO content_genre (
	content_id,
	genre_id
) VALUES (
	#{contentId},
	#{genreId}
)

mapper.update:
UPDATE content_genre
   SET genre_id = #{genreId}
 WHERE content_id = #{contentId}
   AND genre_id = #{genreId}

mapper.delete:
DELETE FROM content_genre
 WHERE content_id = #{contentId}
   AND genre_id = #{genreId}
